const $ = <T extends HTMLElement>(q: string) => document.querySelector<T>(q)!;
const preview = $('#preview') as HTMLCanvasElement;
const previewCtx = preview.getContext('2d')!;
previewCtx.imageSmoothingEnabled = false;
const size = () => ({ w: Math.max(16, Number(($('#frameWidth') as HTMLInputElement).value)), h: Math.max(16, Number(($('#frameHeight') as HTMLInputElement).value)) });
const slot = () => slots[state.slot];
const frames = () => slot().clips[state.clip];
const spec = () => specs.find(s => s.id === state.clip)!;
const clipConfig = () => slot().clipConfig[state.clip];
const pivotFor = (s = slot(), clip = spec()) => clip.anchor === 'seat' ? s.config.seatPivot : s.config.standingPivot;

function updateIds() { const start = Math.max(1, Number(($('#visualStart') as HTMLInputElement).value)); slots.forEach((s, i) => s.visualId = `staff_visual_${String(start + i).padStart(4, '0')}`); renderSlots(); }
function regionsFor(action: ClipId): Region[] { return state.actionOverrides[action] ?? state.baseRegions; }
function editableRegions(): Region[] { return regionsFor(state.clip); }
function normalizeRegion(region: Region): Region { const min = .005; region.w = Math.max(min, Math.min(1, region.w)); region.h = Math.max(min, Math.min(1, region.h)); region.x = Math.max(0, Math.min(1 - region.w, region.x)); region.y = Math.max(0, Math.min(1 - region.h, region.y)); return region; }
function renumberRegions(items: Region[]) { items.forEach((item, i) => item.id = `character_${String(i + 1).padStart(2, '0')}`); }
function renderSliceStatus() { const items = editableRegions(), override = Boolean(state.actionOverrides[state.clip]), rawCount = rawFrames[state.clip].length; $('#sliceCount').textContent = `${items.length} / ${SLOT_COUNT}`; $('#sliceScope').innerHTML = `${override ? `<b>${state.clip}</b> 动作 Override` : '基础批次模板（所有无 Override 动作共用）'}<small>${rawCount ? ` · 已保留 ${rawCount} 个原始帧` : ' · 尚无可重裁原始帧'}</small>`; $('#toggleLock').textContent = items[state.selectedSlice]?.locked ? '解锁切片' : '锁定切片'; ($('#createOverride') as HTMLButtonElement).disabled = override; ($('#clearOverride') as HTMLButtonElement).disabled = !override; ($('#applySlices') as HTMLButtonElement).disabled = !rawCount || items.length !== SLOT_COUNT; syncSliceNumbers(); }
function renderAll() { renderSlots(); renderDetails(); renderSliceStatus(); syncAlignmentControls(); renderTimeline(); renderPreview(); renderQa(); }

function renderSlots() { const used = slots.filter(s => Object.values(s.clips).some(f => f.length)).length; $('#slotSummary').textContent = `${used} / ${SLOT_COUNT}`; $('#slotGrid').innerHTML = slots.map(s => { const actions = Object.values(s.clips).filter(f => f.length).length; return `<button class="slot-chip ${s.index === state.slot ? 'active' : ''} ${actions ? 'filled' : ''}" data-slot="${s.index}" title="${s.visualId}"><b>${String(s.index + 1).padStart(2, '0')}</b><small>${actions}/8</small></button>`; }).join(''); document.querySelectorAll<HTMLElement>('[data-slot]').forEach(el => el.onclick = () => { state.slot = Number(el.dataset.slot); state.selectedSlice = state.slot; state.frame = 0; state.view = 'character'; setViewButtons(); renderAll(); }); }
function renderDetails() { const s = slot(); $('#slotDetails').innerHTML = `<div class="visual-id mono">${s.visualId}</div><div class="action-matrix">${specs.map(c => `<button class="action-row ${c.id === state.clip ? 'active' : ''}" data-action="${c.id}"><span>${s.clips[c.id].length ? '✓' : '○'}</span><b>${c.id}</b><small>${s.clips[c.id].length} 帧</small></button>`).join('')}</div>`; document.querySelectorAll<HTMLElement>('[data-action]').forEach(el => el.onclick = () => selectClip(el.dataset.action as ClipId)); }
function selectClip(id: ClipId) { state.clip = id; state.frame = 0; ($('#importClip') as HTMLSelectElement).value = id; ($('#fps') as HTMLInputElement).value = String(spec().fps); $('#reviewName').textContent = spec().label; renderAll(); }
function setViewButtons() { document.querySelectorAll<HTMLElement>('[data-view]').forEach(el => el.classList.toggle('active-view', el.dataset.view === state.view)); }
function syncSliceNumbers() { const r = editableRegions()[state.selectedSlice], source = state.source; const values = r && source ? [r.x * source.width, r.y * source.height, r.w * source.width, r.h * source.height] : [0, 0, 0, 0]; ['sliceX', 'sliceY', 'sliceW', 'sliceH'].forEach((id, i) => { const input = $(`#${id}`) as HTMLInputElement; input.value = String(Math.round(values[i])); input.disabled = !r || !source || r.locked; }); }
function syncAlignmentControls() { const s = slot(), cfg = clipConfig(), f = frames()[state.frame]; ($('#canonicalScale') as HTMLInputElement).value = s.config.canonicalScale ? s.config.canonicalScale.toFixed(4) : '0'; ($('#standX') as HTMLInputElement).value = String(s.config.standingPivot.x); ($('#standY') as HTMLInputElement).value = String(s.config.standingPivot.y); ($('#seatX') as HTMLInputElement).value = String(s.config.seatPivot.x); ($('#seatY') as HTMLInputElement).value = String(s.config.seatPivot.y); ($('#referenceAction') as HTMLSelectElement).value = s.config.referenceAction; ($('#clipOffsetX') as HTMLInputElement).value = String(cfg.offset.x); ($('#clipOffsetY') as HTMLInputElement).value = String(cfg.offset.y); ($('#frameOffsetX') as HTMLInputElement).value = String(f?.frameOffset.x ?? 0); ($('#frameOffsetY') as HTMLInputElement).value = String(f?.frameOffset.y ?? 0); }

function renderPreview() { previewCtx.clearRect(0, 0, preview.width, preview.height); if (state.view === 'batch') renderBatch(); else renderCharacter(); }
function renderBatch() { if (!state.source) { $('#empty').style.display = 'block'; $('#empty').innerHTML = '<b>导入一批 18 人动作素材</b>随后可像 Photoshop Slice Tool 一样调整每个裁切区域'; return; } $('#empty').style.display = 'none'; const transform = sourceTransform(), items = editableRegions(); previewCtx.drawImage(state.source, transform.ox, transform.oy, transform.dw, transform.dh); items.forEach((r, i) => { const x = transform.ox + r.x * transform.dw, y = transform.oy + r.y * transform.dh, w = r.w * transform.dw, h = r.h * transform.dh, selected = i === state.selectedSlice; previewCtx.fillStyle = selected ? '#78d29418' : '#f0bf6710'; previewCtx.fillRect(x, y, w, h); previewCtx.strokeStyle = r.locked ? '#83908a' : selected ? '#78d294' : '#f0bf67'; previewCtx.lineWidth = selected ? 3 : 1; previewCtx.strokeRect(x, y, w, h); previewCtx.fillStyle = r.locked ? '#4d5751ee' : '#101510dd'; previewCtx.fillRect(x + 3, y + 3, 34, 18); previewCtx.fillStyle = '#efe9d8'; previewCtx.font = '11px monospace'; previewCtx.fillText(`${String(i + 1).padStart(2, '0')}${r.locked ? 'L' : ''}`, x + 6, y + 16); if (selected && !r.locked) drawHandles(x, y, w, h); }); const override = state.actionOverrides[state.clip] ? `${state.clip} Override` : '基础模板'; $('#frameReadout').textContent = `${state.sourceName} · ${items.length}/18 Slice · ${override}`; }
function sourceTransform() { if (!state.source) return { ox: 0, oy: 0, dw: preview.width, dh: preview.height }; const scale = Math.min(preview.width / state.source.width, preview.height / state.source.height), dw = state.source.width * scale, dh = state.source.height * scale; return { ox: (preview.width - dw) / 2, oy: (preview.height - dh) / 2, dw, dh }; }
function drawHandles(x: number, y: number, w: number, h: number) { const points = [[x, y], [x + w / 2, y], [x + w, y], [x + w, y + h / 2], [x + w, y + h], [x + w / 2, y + h], [x, y + h], [x, y + h / 2]]; previewCtx.fillStyle = '#dfffea'; previewCtx.strokeStyle = '#183820'; points.forEach(([px, py]) => { previewCtx.fillRect(px - 4, py - 4, 8, 8); previewCtx.strokeRect(px - 4, py - 4, 8, 8); }); }
function sourcePoint(event: PointerEvent) { const rect = preview.getBoundingClientRect(), px = (event.clientX - rect.left) * preview.width / rect.width, py = (event.clientY - rect.top) * preview.height / rect.height, t = sourceTransform(); return { x: (px - t.ox) / t.dw, y: (py - t.oy) / t.dh }; }
