function animate(time: number) { const list = frames(); if (state.playing && list.length && time - state.tick > 1000 / spec().fps) { const next = state.frame + 1; if (next >= list.length && !spec().loop) state.playing = false; else state.frame = next % list.length; state.tick = time; renderTimeline(); renderPreview(); } requestAnimationFrame(animate); }

$('#mediaInput').addEventListener('change', e => { const files = (e.target as HTMLInputElement).files; if (files?.length) importMedia(files).catch(err => alert(err.message)); });
$('#visualStart').addEventListener('change', updateIds); $('#importClip').addEventListener('change', e => selectClip((e.target as HTMLSelectElement).value as ClipId)); $('#tolerance').addEventListener('input', e => $('#toleranceOut').textContent = (e.target as HTMLInputElement).value);
function updateSliceNumber() { const r = editableRegions()[state.selectedSlice], source = state.source; if (!r || !source || r.locked) return; r.x = Number(($('#sliceX') as HTMLInputElement).value) / source.width; r.y = Number(($('#sliceY') as HTMLInputElement).value) / source.height; r.w = Number(($('#sliceW') as HTMLInputElement).value) / source.width; r.h = Number(($('#sliceH') as HTMLInputElement).value) / source.height; normalizeRegion(r); renderSliceStatus(); renderPreview(); }
['sliceX', 'sliceY', 'sliceW', 'sliceH'].forEach(id => $(`#${id}`).addEventListener('change', updateSliceNumber));
$('#canvasPreset').addEventListener('change', e => { const value = (e.target as HTMLSelectElement).value; if (value !== 'custom') { const [w, h] = value.split('x'); ($('#frameWidth') as HTMLInputElement).value = w; ($('#frameHeight') as HTMLInputElement).value = h; slots.forEach(rebuildSlot); renderAll(); } });
function canvasSizeChanged() { ($('#canvasPreset') as HTMLSelectElement).value = 'custom'; slots.forEach(rebuildSlot); renderAll(); }
$('#frameWidth').addEventListener('change', canvasSizeChanged); $('#frameHeight').addEventListener('change', canvasSizeChanged);
$('#establishBaseline').onclick = () => { const f = frames()[state.frame]; if (!f) return alert('先导入并选中一个参考动作帧。'); const b = findBounds(f.raw.getContext('2d')!.getImageData(0, 0, f.raw.width, f.raw.height)); if (!b) return alert('当前帧没有可见角色。'); slot().config.canonicalScale = Math.min((size().h - 12) / b.height, (size().w - 8) / b.width); slot().config.referenceAction = state.clip; slot().clipConfig[state.clip].sourcePivot = { x: b.x + b.width / 2, y: b.y + b.height }; rebuildSlot(); renderAll(); };
$('#canonicalScale').addEventListener('change', e => { slot().config.canonicalScale = Math.max(0.001, Number((e.target as HTMLInputElement).value)); rebuildSlot(); renderAll(); });
function updatePivot() { slot().config.standingPivot = { x: Number(($('#standX') as HTMLInputElement).value), y: Number(($('#standY') as HTMLInputElement).value) }; slot().config.seatPivot = { x: Number(($('#seatX') as HTMLInputElement).value), y: Number(($('#seatY') as HTMLInputElement).value) }; rebuildSlot(); renderAll(); }
['standX', 'standY', 'seatX', 'seatY'].forEach(id => $(`#${id}`).addEventListener('change', updatePivot));
$('#referenceAction').addEventListener('change', e => { slot().config.referenceAction = (e.target as HTMLSelectElement).value as ClipId; renderPreview(); });
function updateClipOffset() { clipConfig().offset = { x: Number(($('#clipOffsetX') as HTMLInputElement).value), y: Number(($('#clipOffsetY') as HTMLInputElement).value) }; frames().forEach(f => rebuildFrame(slot(), state.clip, f)); renderAll(); }
['clipOffsetX', 'clipOffsetY'].forEach(id => $(`#${id}`).addEventListener('change', updateClipOffset));
function updateFrameOffset() { const f = frames()[state.frame]; if (!f) return; f.frameOffset = { x: Number(($('#frameOffsetX') as HTMLInputElement).value), y: Number(($('#frameOffsetY') as HTMLInputElement).value) }; rebuildFrame(slot(), state.clip, f); renderAll(); }
['frameOffsetX', 'frameOffsetY'].forEach(id => $(`#${id}`).addEventListener('change', updateFrameOffset));
$('#onion').addEventListener('change', e => { state.onion = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#onionOpacity').addEventListener('input', e => { state.onionOpacity = Number((e.target as HTMLInputElement).value); renderPreview(); });
$('#showBounds').addEventListener('change', e => { state.showBounds = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#showAnchor').addEventListener('change', e => { state.showAnchor = (e.target as HTMLInputElement).checked; renderPreview(); }); $('#fps').addEventListener('change', e => { spec().fps = Math.max(1, Math.min(30, Number((e.target as HTMLInputElement).value))); renderDetails(); });
$('#play').onclick = () => { state.playing = !state.playing; $('#play').textContent = state.playing ? '❚❚ 暂停' : '▶ 播放'; }; $('#prev').onclick = () => { if (frames().length) { state.frame = (state.frame - 1 + frames().length) % frames().length; syncAlignmentControls(); renderTimeline(); renderPreview(); } }; $('#next').onclick = () => { if (frames().length) { state.frame = (state.frame + 1) % frames().length; syncAlignmentControls(); renderTimeline(); renderPreview(); } };
$('#deleteFrame').onclick = () => { if (frames().length) { frames().splice(state.frame, 1); state.frame = Math.max(0, Math.min(state.frame, frames().length - 1)); renderAll(); } }; $('#duplicateFrame').onclick = () => { const f = frames()[state.frame]; if (f) { const raw = document.createElement('canvas'); raw.width = f.raw.width; raw.height = f.raw.height; raw.getContext('2d')!.drawImage(f.raw, 0, 0); const copy = { ...f, raw, canvas: document.createElement('canvas'), frameOffset: { ...f.frameOffset }, sliceRect: { ...f.sliceRect } }; rebuildFrame(slot(), state.clip, copy); frames().splice(state.frame + 1, 0, copy); state.frame++; renderAll(); } }; $('#flipFrame').onclick = () => { const f = frames()[state.frame]; if (f) { f.raw = flip(f.raw); rebuildFrame(slot(), state.clip, f); renderAll(); } }; $('#sampleFrames').onclick = recommendedSample;
$('#mirrorRight').onclick = () => { const s = slot(); if (!s.clips.walk_left.length) return alert('当前 Slot 没有 Walk Left'); if (s.clips.walk_right.length && !confirm('覆盖已有 Walk Right？')) return; const leftPivot = s.clipConfig.walk_left.sourcePivot; s.clipConfig.walk_right = { offset: { ...s.clipConfig.walk_left.offset }, sourcePivot: leftPivot ? { x: s.clips.walk_left[0].raw.width - leftPivot.x, y: leftPivot.y } : null }; s.clips.walk_right = s.clips.walk_left.map(f => { const mirrored: Frame = { ...f, raw: flip(f.raw), canvas: document.createElement('canvas'), frameOffset: { x: -f.frameOffset.x, y: f.frameOffset.y }, sliceRect: { ...f.sliceRect } }; rebuildFrame(s, 'walk_right', mirrored); return mirrored; }); selectClip('walk_right'); };
$('#saveBatch').onclick = saveBatch; $('#exportBatch').onclick = () => exportBatch().catch(err => alert(err.message)); $('#newBatch').onclick = reset; $('#openBatch').addEventListener('change', e => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) { clearRawFrames(); openBatch(f).catch(err => alert(err.message)); } }); $('#saveLayout').onclick = saveLayout; $('#loadLayout').addEventListener('change', e => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) loadLayout(f).catch(err => alert(err.message)); }); $('#styleGuide').onclick = () => ($('#styleDialog') as HTMLDialogElement).showModal();
$('#applySlices').onclick = applySlicesToCurrentAction;
$('#resetGrid').onclick = () => { const fresh = gridRegions(); if (state.actionOverrides[state.clip]) state.actionOverrides[state.clip] = fresh; else state.baseRegions = fresh; state.selectedSlice = 0; renderAll(); };
$('#createOverride').onclick = () => { state.actionOverrides[state.clip] = cloneRegions(state.baseRegions); state.selectedSlice = Math.min(state.selectedSlice, SLOT_COUNT - 1); renderAll(); };
$('#clearOverride').onclick = () => { delete state.actionOverrides[state.clip]; state.selectedSlice = Math.min(state.selectedSlice, state.baseRegions.length - 1); renderAll(); };
$('#toggleLock').onclick = () => { const item = editableRegions()[state.selectedSlice]; if (item) { item.locked = !item.locked; renderAll(); } };
$('#deleteSlice').onclick = () => { const items = editableRegions(), item = items[state.selectedSlice]; if (!item || item.locked) return; items.splice(state.selectedSlice, 1); renumberRegions(items); state.selectedSlice = Math.max(0, Math.min(state.selectedSlice, items.length - 1)); state.slot = state.selectedSlice; renderAll(); };
$('#addSlice').onclick = () => { const items = editableRegions(); if (items.length >= SLOT_COUNT) return alert('当前已经有 18 个切片。先删除一个，再创建新切片。'); items.push({ id: `character_${String(items.length + 1).padStart(2, '0')}`, x: .35, y: .35, w: .3, h: .3, locked: false }); state.selectedSlice = items.length - 1; state.slot = state.selectedSlice; state.view = 'batch'; setViewButtons(); renderAll(); };
document.querySelectorAll<HTMLElement>('[data-view]').forEach(el => el.onclick = () => { state.view = el.dataset.view as 'batch' | 'character'; setViewButtons(); renderPreview(); }); document.querySelectorAll<HTMLElement>('[data-bg]').forEach(el => el.onclick = () => { const bg = el.dataset.bg!; $('#stage').className = `stage ${bg === 'checker' ? '' : bg}`; });
preview.addEventListener('pointerdown', beginSliceInteraction); preview.addEventListener('pointermove', updateSliceInteraction); preview.addEventListener('pointerup', endSliceInteraction); preview.addEventListener('pointercancel', endSliceInteraction);

updateIds(); renderAll(); requestAnimationFrame(animate);
